import {enrichment} from './enrichment-data.js';
import { resourceCatalog } from './resources-data.js';
import { guides } from './learning-content.js';
import { visualMarkup, bindVisual } from './visual-lessons.js';
import { icon } from './icons.js';
import { mountParabola, mountDeterminant, mountCircle, mountTangent } from './playground.js';
export {resourceCatalog};
const P=(fr,en)=>[fr,en];
const E=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const courses={seconde:P('Seconde','Seconde'),premiere:P('Première spécialité','Première · mathematics specialty'),terminale:P('Terminale spécialité','Terminale · mathematics specialty'),stmg:P('Terminale STMG','Terminale STMG')};
const kinds={chapter:P('Chapitre élève · cours, activités et exercices','Student chapter · lessons, activities and exercises'),teacher:P('Édition professeur · corrections et conseils','Teacher edition · solutions and guidance'),fluency:P('Automatismes · fiche élève','Fluency · student worksheet'),'fluency-solutions':P('Automatismes · corrigé','Fluency · solutions')};
const tabs={understand:P('Comprendre','Understand'),experiment:P('Expérimenter','Experiment'),practice:P('S’entraîner','Practise'),documents:P('Documents','Documents')};
let filter='seconde',query='';
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function matchingChapters(course,search){const q=normalize(search.trim());return resourceCatalog.chapters.filter(c=>(course==='all'||c.course===course)&&(!q||normalize([...c.title,c.course,c.topic].join(' ')).includes(q)));}
export function matchingSupplements(course,search){const q=normalize(search.trim());return resourceCatalog.supplements.filter(c=>(course==='all'||c.course===course)&&(!q||normalize([...c.title,c.course,c.kind].join(' ')).includes(q)));}
function supplementCards(items,t){return items.length?`<div class="course-supplements"><h3>${t(P('Banques d’exercices & préparation','Exercise banks & preparation'))}</h3>${items.map(c=>`<details class="supplement-card"><summary>${E(t(c.title))}</summary>${fileLink(c.files[0],t(P('Version élève','Student version')))}<details><summary>${t(P('Version professeur / corrections','Teacher version / solutions'))}</summary>${fileLink(c.files[1],t(P('Ouvrir la version professeur','Open the teacher version')))}<p class="document-meta">${t(P('Les versions peuvent inclure des variantes différentes : compare les énoncés.','The editions may contain different variants: compare the questions.'))}</p></details></details>`).join('')}</div>`:'';}
function workshopCards(t){const q=normalize(query.trim());const found=enrichment.filter(p=>(!q||normalize([...p.title,...p.prerequisites,...p.level].join(' ')).includes(q)));return found.length?`<section class="course-group enrichment-group workshops"><div class="course-title"><h2>${t(P('Ateliers & approfondissements','Workshops & enrichment'))}</h2><span>${found.length} · FR / EN</span></div><p class="group-note">${t(P('Une méthode, quatre exercices progressifs et un problème de synthèse, avec solutions séparées.','A method, four progressive exercises and a synthesis problem, with separate solutions.'))}</p><div class="rail">${found.map((p,i)=>`<a class="tile cat-ws enrichment-card" data-reveal style="--i:${i}" href="#library/explore-${p.id}"><span class="tile-art" aria-hidden="true">${String(enrichment.indexOf(p)+1).padStart(2,'0')}</span><span class="tile-no">${t(P('Atelier','Workshop'))}</span><h3>${E(t(p.title))}</h3><span class="tile-chips"><span>${E(t(p.level))}</span></span><span class="tile-go">${t(P('Explorer','Explore'))}${icon('arrow-right',18)}</span></a>`).join('')}</div></section>`:'';}
const tabLabels={seconde:P('Seconde','Seconde'),premiere:P('Première','Première'),terminale:P('Terminale','Terminale'),stmg:P('STMG','STMG')};
const topicArt={arithmetic:['ℕ','alg'],vectors:['→','geo'],lines:['y=ax','geo'],intervals:['[a;b]','alg'],reasoning:['⇒','alg'],functions:['f(x)','ana'],statistics:['x̄','data'],algebra:['a+b','alg'],proportions:['%','data'],variations:['f′','ana'],conditioning:['P(A|B)','data'],sequences:['uₙ','ana'],quadratic:['ax²','alg'],derivative:['f′','ana'],randomvariables:['E(X)','data'],exponential:['eˣ','ana'],trigonometry:['θ','geo'],space:['xyz','geo'],limitsseq:['lim','ana'],limitsfunction:['lim','ana'],combinatorics:['n!','data'],binomial:['B(n;p)','data'],logarithm:['ln','ana'],orthogonal:['⊥','geo'],primitives:['∫','ana'],integral:['∫','ana'],lln:['n→∞','data'],log10:['log','ana'],reciprocal:['1/x','ana'],regression:['ŷ','data']};
function tile(c,t,i){const [glyph,cat]=topicArt[c.topic]||['∑','alg'];const fluent=c.files.some(f=>f.kind==='fluency');return `<a class="tile cat-${cat}" data-reveal style="--i:${i}" href="#chapter/${c.id}"><span class="tile-art" aria-hidden="true">${E(glyph)}</span><span class="tile-no">${String(c.number).padStart(2,'0')}</span><h3>${E(t(c.title))}</h3><span class="tile-chips"><span>${t(P('Cours','Lessons'))}</span><span>${t(P('Exercices','Exercises'))}</span><span>${t(P('Corrigés','Solutions'))}</span>${fluent?`<span>${t(P('Automatismes','Fluency'))}</span>`:''}</span><span class="tile-go">${t(P('Ouvrir','Open'))}${icon('arrow-right',18)}</span></a>`;}
function cards(t){const scope=query.trim()?'all':filter;const found=matchingChapters(scope,query),extra=matchingSupplements(scope,query);const workshops=workshopCards(t);return `<p class="resource-count" role="status">${query.trim()?`${found.length} ${t(P('chapitres trouvés','chapters found'))}`:`${found.length} ${t(P('chapitres','chapters'))} · ${extra.length} ${t(P('ressources de préparation','preparation resources'))}`}</p>${Object.entries(courses).filter(([id])=>[...found,...extra].some(c=>c.course===id)).map(([id,title])=>`<section class="course-group"><div class="course-title"><h2>${E(t(title))}</h2><span>2026-2027</span></div><div class="tile-grid">${found.filter(c=>c.course===id).map((c,i)=>tile(c,t,i)).join('')}</div>${supplementCards(extra.filter(c=>c.course===id),t)}</section>`).join('')}${workshops}${found.length||extra.length||workshops?'':`<div class="resource-empty"><p>${t(P('Aucune ressource ne correspond à cette recherche.','No resources match this search.'))}</p><button data-clear-search>${t(P('Effacer les filtres','Clear filters'))}</button></div>`}`;}
const glyphs=['∑','□','▦','⋮','≡','n³','≥','n²'];
export function libraryPage(t,{challenges=[],completed=new Set()}={}){documentLanguage=t(P('fr','en'));const counts=Object.fromEntries(Object.keys(courses).map(id=>[id,resourceCatalog.chapters.filter(c=>c.course===id).length]));const feature=[challenges[0],challenges[3],challenges[7]].filter(Boolean);const gestures=[['lightbulb',P('Prédire','Predict'),P('Devine ce qui va changer avant de toucher à rien.','Guess what will change before you touch anything.')],['cursor-click',P('Expérimenter','Experiment'),P('Déplace un point, tire un curseur, observe les nombres.','Move a point, drag a slider, watch the numbers.')],['pencil-simple-line',P('Conjecturer','Conjecture'),P('Écris ce qui semble toujours vrai, et dans quelles conditions.','Write what seems always true, and under which conditions.')],['chat-circle-text',P('Expliquer','Explain'),P('Trouve pourquoi, avec une formule ou un argument.','Find why, with a formula or an argument.')],['seal-check',P('Vérifier','Check'),P('Réponds à une question ciblée, puis compare avec la solution.','Answer one focused question, then compare with the solution.')]];return `<main id="main" tabindex="-1" class="page resource-page home">
<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><h1 id="hero-title">${t(P('Bouge un point.<br><em>Vois la règle.</em>','Move a point.<br><em>See the rule.</em>'))}</h1><p class="lede">${t(P('Chaque chapitre commence par une expérience à manipuler. La règle vient ensuite, et tu sais pourquoi elle marche.','Every chapter starts with something to move. The rule comes after, and you know why it works.'))}</p><div class="hero-cta"><button class="btn btn-primary" data-scroll="chapitres">${t(P('Choisir un chapitre','Choose a chapter'))}${icon('arrow-right',20)}</button><a class="btn btn-ghost" href="#lab">${icon('flask',20)}${t(P('Ouvrir le laboratoire','Open the laboratory'))}</a></div></div><figure class="toy toy-hero" id="toy-parabola" aria-label="${t(P('Expérience : une parabole et ses racines','Experiment: a parabola and its roots'))}"></figure></section>
<section class="playground" aria-labelledby="pg-title"><h2 id="pg-title" data-reveal>${t(P('Trois idées, un seul geste : déplacer.','Three ideas, one gesture: move.'))}</h2><div class="toy-grid3"><article class="toy-card toy-card-det" data-reveal><header><h3>${t(P('Le déterminant est une aire','The determinant is an area'))}</h3><p>${t(P('Si l’aire est nulle, les vecteurs sont colinéaires.','If the area is zero, the vectors are collinear.'))}</p></header><figure id="toy-det"></figure><a class="toy-link" href="#lab/vectors">${t(P('Laboratoire des vecteurs','Vectors laboratory'))}${icon('arrow-up-right',18)}</a></article><article class="toy-card toy-card-circle" data-reveal style="--i:1"><header><h3>${t(P('Le cercle donne cos et sin','The circle gives cos and sin'))}</h3><p>${t(P('Fais tourner le point P.','Turn the point P.'))}</p></header><figure id="toy-circle"></figure><a class="toy-link" href="#lab/trig">${t(P('Laboratoire de trigonométrie','Trigonometry laboratory'))}${icon('arrow-up-right',18)}</a></article><article class="toy-card toy-card-tangent" data-reveal style="--i:2"><header><h3>${t(P('La tangente est une limite','The tangent is a limit'))}</h3><p>${t(P('Rapproche Q de A.','Bring Q close to A.'))}</p></header><figure id="toy-tangent"></figure><a class="toy-link" href="#lab/derivative">${t(P('Laboratoire de dérivation','Derivative laboratory'))}${icon('arrow-up-right',18)}</a></article></div></section>
<section class="chapters" id="chapitres" tabindex="-1" aria-labelledby="chapters-title"><div class="chapters-head"><h2 id="chapters-title">${t(P('Choisis ton chapitre','Choose your chapter'))}</h2><p>${t(P('47 chapitres de la Seconde à la Terminale. Chacun a trois temps : comprendre, expérimenter, s’entraîner.','47 chapters from Seconde to Terminale. Each has three parts: understand, experiment, practise.'))}</p></div><div class="chapter-tools"><div class="tabs" role="group" aria-label="${t(P('Niveau','Level'))}">${Object.keys(tabLabels).map(id=>`<button class="tab" data-course="${id}" aria-pressed="${filter===id}">${t(tabLabels[id])}<span>${counts[id]}</span></button>`).join('')}</div><label class="search"><span class="sr-only">${t(P('Rechercher un chapitre','Find a chapter'))}</span>${icon('magnifying-glass',20)}<input id="resource-search" type="search" value="${E(query)}" placeholder="${t(P('Suites, logarithme, probabilités…','Sequences, logarithm, probability…'))}"></label></div><p class="catalogue-link"><a href="#workshop/quadratic">${t(P('Trinôme : présenter et explorer en cinq étapes','Quadratics: present and explore in five stages'))}</a><a href="#library">${t(P('Tous les fichiers : filtrer par type, langue et parcours','All files: filter by type, language and pathway'))}</a></p><div id="resource-results">${cards(t)}</div></section>
<section class="gestures" aria-labelledby="gestures-title"><h2 id="gestures-title" data-reveal>${t(P('Cinq gestes, dans cet ordre','Five moves, in this order'))}</h2><p class="group-note" data-reveal>${t(P('Une expérience donne des indices, pas une preuve. La preuve vient à la fin.','An experiment gives evidence, not proof. The proof comes last.'))}</p><ol class="gesture-path">${gestures.map(([ic,name,text],i)=>`<li class="gesture" data-reveal style="--i:${i}"><span class="gesture-icon">${icon(ic,26)}</span><h3>${t(name)}</h3><p>${t(text)}</p></li>`).join('')}</ol></section>
${feature.length?`<section class="arena" aria-labelledby="arena-title"><div class="arena-head" data-reveal><h2 id="arena-title">${t(P('Un défi pour la route','A challenge for the road'))}</h2><a class="btn btn-ghost" href="#challenges">${t(P('Voir les 8 défis','See all 8 challenges'))}${icon('arrow-right',20)}</a></div><div class="arena-grid">${feature.map((c,i)=>`<a class="challenge-card arena-card${i===0?' arena-main':''}" data-reveal style="--i:${i}" href="#challenges/${c.id}"><span class="challenge-motif" aria-hidden="true">${glyphs[challenges.indexOf(c)]}</span><span class="tag ${c.type}">${c.type==='play'?t(P('Récréatif','Recreational')):t(P('Olympiade','Olympiad'))}</span><h3>${E(t(c.title))}</h3>${i===0?`<p>${E(t(c.prompt))}</p>`:''}<span class="card-bottom"><span>${'●'.repeat(c.difficulty)}${'○'.repeat(3-c.difficulty)}<span class="sr-only"> ${t(P('Difficulté','Difficulty'))} ${c.difficulty}/3</span></span><span>${completed.has(c.id)?t(P('Réponse trouvée','Answer found')):c.minutes+' min'}</span></span></a>`).join('')}</div></section>`:''}
<details class="resource-origin"><summary>${t(P('D’où viennent ces ressources ?','Where do these resources come from?'))}</summary><p>${t(P('Les livrets sont disponibles en français et en anglais. Les guides essentiels et graphiques accompagnent chaque chapitre.','The booklets are available in French and English. Essential guides and diagrams accompany each chapter.'))}</p><p>${t(P('Les documents correspondent à l’édition du 8 octobre 2026.','The documents are from the 8 October 2026 edition.'))}</p><p>${t(P('Inspiration : simulations de Javalab et parcours cours-exercices de Mathoutils. Les animations de ce site sont interactives et calculées dans le navigateur.','Inspiration: Javalab simulations and Mathoutils lesson-exercise pathways. This site’s animations are interactive and computed in your browser.'))}</p><a href="https://javalab.org/en/" target="_blank" rel="noopener">Javalab</a> · <a href="https://www.mathoutils.fr/" target="_blank" rel="noopener">Mathoutils</a></details></main>`;}
export function bindLibrary(t,{lang='fr',reduced=()=>false,fx=()=>{}}={}){const results=document.querySelector('#resource-results');const stops=[];const lazy=(sel,mount)=>{const el=document.querySelector(sel);if(el)stops.push(mount(el,{lang,reduced}));};lazy('#toy-parabola',mountParabola);lazy('#toy-det',mountDeterminant);lazy('#toy-circle',mountCircle);lazy('#toy-tangent',mountTangent);const paint=()=>{results.innerHTML=cards(t);document.querySelectorAll('.tab').forEach(b=>b.setAttribute('aria-pressed',String(!query.trim()&&b.dataset.course===filter)));fx();const clear=results.querySelector('[data-clear-search]');clear?.addEventListener('click',()=>{filter='seconde';query='';document.querySelector('#resource-search').value='';paint();});};document.querySelector('#resource-search').addEventListener('input',e=>{query=e.target.value;paint();});document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.course;query='';document.querySelector('#resource-search').value='';paint();}));document.querySelectorAll('[data-scroll]').forEach(b=>b.addEventListener('click',()=>{const target=document.getElementById(b.dataset.scroll);target?.scrollIntoView({behavior:reduced()?'auto':'smooth',block:'start'});target?.focus({preventScroll:true});}));paint();return()=>stops.forEach(stop=>stop?.());}
let documentLanguage='fr';
const fileLink=(f,label,page=1)=>`<a class="document-link" href="./${documentLanguage==='en'?f.englishPath:f.path}#page=${page}" target="_blank" rel="noopener">${E(label)} <span>PDF · FR / EN · ${f.pages} p.</span></a>`;
function documentCards(c,t){return c.files.map(f=>{const source=resourceCatalog.sources.find(s=>s.name===f.source);const teacher=f.kind==='teacher'||f.kind==='fluency-solutions';const links=Object.entries(f.sections||{}).filter(([k])=>['lesson','practice','problem','quiz'].includes(k)).map(([k,p])=>fileLink(f,t({lesson:P('Cours / activités','Lessons / activities'),practice:P('Exercices','Exercises'),problem:P('Problèmes','Problems'),quiz:P('QCM','Multiple choice')}[k]),p)).join('');const label=t(kinds[f.kind])+(f.title?' · '+t(f.title):'');const body=`${fileLink(f,label)}${links?`<div class="section-links">${links}</div>`:''}<p class="document-meta">${t(P('Pages du document source','Source document pages'))} ${f.start}–${f.end} · ${t(P('Modifié le','Modified'))} ${source.modified.slice(0,10)}</p>`;return teacher?`<details class="document-card"><summary>${E(label)}</summary>${body}</details>`:`<article class="document-card">${body}</article>`;}).join('');}
function sourcePractice(c,t){const f=c.files.find(f=>f.kind==='chapter');return `<div class="source-practice"><h2>${t(P('Poursuivre dans ton livret','Continue in your booklet'))}</h2><p>${t(P('Le chapitre complet contient les activités et les exercices de ton niveau. Certaines pages mêlent cours et entraînement.','The full chapter contains activities and exercises for your course. Some pages combine lessons and practice.'))}</p>${fileLink(f,t(P('Ouvrir les exercices du chapitre','Open the chapter exercises')),f.sections?.practice||1)}<details><summary>${t(P('Consulter la version professeur après avoir cherché','Read the teacher version after trying'))}</summary>${fileLink(c.files.find(f=>f.kind==='teacher'),t(P('Corrections et conseils','Solutions and guidance')))}${c.course==='premiere'?`<p>${t(P('Attention : le PDF élève du 18 septembre est plus récent que la version professeur du 10 septembre. Compare les énoncés avant d’utiliser une correction.','Note: the student PDF from 18 September is newer than the teacher version from 10 September. Compare the questions before using a solution.'))}</p>`:''}</details></div>`;}
export function chapterPage(id,tab,t,labs){documentLanguage=t(P('fr','en'));const c=resourceCatalog.chapters.find(c=>c.id===id),g=guides[c.topic];tab=Object.hasOwn(tabs,tab)?tab:'understand';const lab=g.lab?labs.find(l=>l.id===g.lab):null;const nearby=resourceCatalog.chapters.filter(x=>x.course===c.course);const prev=nearby.find(x=>x.number===c.number-1),next=nearby.find(x=>x.number===c.number+1);const visual=visualMarkup(g.scene,t);let body='';
 if(tab==='understand')body=`<div class="chapter-workbench"><article class="companion"><span class="eyebrow">${t(P('Guide essentiel','Essential guide'))}</span><h2>${t(P('L’idée à retenir','The central idea'))}</h2><p class="central-idea">${E(t(g.idea))}</p><ul class="lesson-facts">${g.facts.map(f=>`<li>${E(t(f))}</li>`).join('')}</ul><section class="worked-example"><h3>${t(P('Exemple expliqué','Worked example'))}</h3><p>${E(t(g.example.question))}</p><ol>${g.example.steps.map(s=>`<li>${E(t(s))}</li>`).join('')}</ol></section><p class="companion-scope">${t(P('Ce guide met en lumière une idée centrale du chapitre. Pour l’ensemble des notions, consulte le livret complet dans Documents.','This guide highlights one central idea from the chapter. For the full set of topics, read the complete booklet in Documents.'))}</p></article>${visual}</div>`;
 if(tab==='experiment')body=`<div class="experiment-chapter">${visual}<aside class="experiment-prompts"><h2>${t(P('Prédire, observer, expliquer','Predict, observe, explain'))}</h2><ol><li>${t(P('Avant de déplacer le curseur, prédis ce qui va changer.','Before moving the slider, predict what will change.'))}</li><li>${t(P('Teste deux valeurs très différentes. Lis aussi les valeurs du modèle.','Test two very different values. Read the model values too.'))}</li><li>${t(P('Explique ce qui reste invariant avec une équation ou une propriété.','Explain what stays invariant using an equation or a property.'))}</li></ol>${lab?`<a class="lab-jump" href="#lab/${lab.id}">${t(P('Explorer librement :','Explore freely:'))} ${E(t(lab.title))}</a><p>${t(P('Dans le laboratoire, les points se déplacent directement à la souris, au toucher ou au clavier.','In the laboratory, move the points directly using a mouse, touch or keyboard.'))}</p>`:''}</aside></div>`;
 if(tab==='practice')body=`<div class="practice-layout"><article class="practice-card"><span class="eyebrow">${t(P('À toi de jouer','Your turn'))}</span><h2>${t(P('Transférer l’idée','Apply the idea'))}</h2><p>${E(t(g.practice.question))}</p><label>${t(P('Ton raisonnement (conservé pendant cette session)','Your reasoning (kept for this session)'))}<textarea id="chapter-answer" rows="5" placeholder="${t(P('Écris les étapes de ton raisonnement…','Write the steps of your reasoning…'))}"></textarea></label><details><summary>${t(P('Un indice','A hint'))}</summary><p>${E(t(g.practice.hint))}</p></details><details><summary>${t(P('Comparer avec la solution','Compare with the solution'))}</summary><p>${E(t(g.practice.solution))}</p><p>${t(P('Compare les étapes, les hypothèses et la conclusion avec ton raisonnement.','Compare the steps, assumptions and conclusion with your reasoning.'))}</p></details></article>${sourcePractice(c,t)}</div>`;
 if(tab==='documents')body=`<p class="document-intro">${t(P('Documents en français et en anglais, téléchargeables chapitre par chapitre. La langue du site détermine celle du PDF. Les liens de section sont des repères : une page peut contenir plusieurs types de contenu.','French and English documents, available chapter by chapter. The site language selects the PDF language. Section links are pointers: a page may contain several types of content.'))}</p>${c.course==='premiere'?`<p class="edition-note">${t(P('Le livret élève est daté du 18 septembre 2026 ; le livret professeur du 10 septembre. Vérifie que l’énoncé correspond avant de consulter sa correction.','The student booklet is dated 18 September 2026; the teacher booklet 10 September. Check that the question matches before consulting its solution.'))}</p>`:''}<p><a class="lab-jump" href="#library/${c.id}">${t(P("Notes, exercices et problèmes en fichiers séparés","Notes, exercises and problems as separate files"))}</a></p><div class="document-grid">${documentCards(c,t)}</div>`;
 return `<main id="main" tabindex="-1" class="page chapter-page"><a class="back-library" href="#resources">${t(P('Tous les chapitres','All chapters'))}</a><div class="chapter-heading"><span class="eyebrow">${E(t(courses[c.course]))} · ${t(P('Chapitre','Chapter'))} ${c.number}</span><h1>${E(t(c.title))}</h1></div><nav class="chapter-tabs" aria-label="${t(P('Sections du chapitre','Chapter sections'))}">${Object.entries(tabs).map(([key,title])=>`<a href="#chapter/${c.id}/${key}" ${key===tab?'aria-current="page"':''}>${E(t(title))}</a>`).join('')}</nav>${body}<nav class="chapter-next" aria-label="${t(P('Ordre des chapitres','Chapter order'))}">${prev?`<a href="#chapter/${prev.id}">${t(P('Précédent','Previous'))} · ${E(t(prev.title))}</a>`:'<span></span>'}${next?`<a href="#chapter/${next.id}">${t(P('Suivant','Next'))} · ${E(t(next.title))}</a>`:''}</nav></main>`;
}
const answers=new Map();
export function bindChapter(id,t,fmt){const c=resourceCatalog.chapters.find(c=>c.id===id);const root=document.querySelector('.visual-lesson');const answer=document.querySelector('#chapter-answer');if(answer){answer.value=answers.get(id)||'';answer.addEventListener('input',()=>answers.set(id,answer.value));}return root?bindVisual(root,guides[c.topic].scene,t,fmt):()=>{};}
export function relatedChapters(labId,t){const related=resourceCatalog.chapters.filter(c=>guides[c.topic]?.lab===labId);return related.length?`<details class="related-chapters"><summary>${t(P('Cours et exercices liés','Related lessons and exercises'))}</summary><div>${related.map(c=>`<a href="#chapter/${c.id}">${E(t(courses[c.course]))} · ${E(t(c.title))}</a>`).join('')}</div></details>`:'';}
